"""Concise full-set S2 report with current results and a filtered answer browser."""
import json
import hashlib
from html import escape as e
from pathlib import Path
from urllib.parse import urlencode
from site_navigation import project_tabs,experiment_subtabs
from build_answering_results import CSS,table,link
ROOT=Path(__file__).resolve().parents[1]
NAMES={'reactive':'Reactive','current_notes':'Current notes','quotes_current':'Source quotes','quotes_history':'Quotes + earlier evidence','function_notes':'Function notes'}
MODELS={'instruct':'Qwen3-30B Instruct','thinking':'Qwen3-30B Thinking','minicpm':'MiniCPM-o 4.5','qwen-thinking':'Qwen3-Omni Thinking'}
IDENTITY={'ground_truth_transcript':'Reference speaker labels','audio_only':'Audio alone','labelled_voices':'Labelled past voices'}

def asset(name):
 path=ROOT/'research/note-functions'/name
 return '../research/note-functions/'+name+'?v='+hashlib.sha256(path.read_bytes()).hexdigest()[:12]

def read(name):return json.loads((ROOT/'research/note-functions'/name).read_text())
def number(value,digits=0):return '—'if value is None else f'{value:,.{digits}f}'
def interval(m,digits=1):
 if m['mean_change']is None:return 'Not exposed'
 low,high=m['meeting_95_percent_interval'];return f"{m['mean_change']:+,.{digits}f} [{low:+,.{digits}f}, {high:+,.{digits}f}]"
def score(row):
 if row['scored']==row['planned']:return f"{row['supported_correct']}/{row['planned']} ({100*row['supported_correct']/row['planned']:.1f}%)"
 return f"{row['supported_correct']}/{row['scored']} scored; {row['missing_judgments']} pending"

JS=r'''
(()=>{
 const $=id=>document.getElementById(id), make=(tag,text,cls)=>{let x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;};
 const models=MODEL_NAMES,conditions=CONDITION_NAMES;
 let data=null,cases=null;
 function render(){
  if(!data)return;const q=cases.find(x=>x.id==$('case-question').value),host=$('case-list');host.replaceChildren();
  host.append(make('h3',q.question),make('p',q.meeting+' · question at '+(q.at/60).toFixed(1)+' minutes.'));
  const facts=make('ul');q.minimum_facts.forEach(f=>facts.append(make('li',f)));host.append(make('p','Reference facts:'),facts);
  const detail=make('details');detail.append(make('summary','Supporting transcript excerpts'));const speech=make('ul');q.source_evidence.forEach(s=>speech.append(make('li',s.id+' · '+s.speaker+' · '+s.start.toFixed(2)+' s: '+s.text)));detail.append(speech);host.append(detail);
  const rows=data.answers.filter(r=>r.question_id===q.id&&r.model===$('case-model').value&&($('case-seed').value==='all'||String(r.seed)===$('case-seed').value)&&($('case-voice').value==='all'||r.identity===$('case-voice').value));
  rows.forEach(r=>{const card=make('article',undefined,'case-card');card.append(make('h4',conditions[r.condition]+' · '+r.identity.replaceAll('_',' ')+' · seed '+r.seed),make('pre',r.evaluation_text||r.answer||'[No final answer text]','native'));
   const evaluated=r.score===null?'Pending':r.score.supported_correct?'Fully supported':'Does not meet the reference facts or has an unsupported claim';
   card.append(make('p','Score: '+evaluated+' · '+(r.source.startsWith('automatic')?'automatic, provisional':r.source==='pending'?'review pending':'source reviewed')));
   card.append(make('p','Request-time thinking: '+(r.thinking_tokens===null?(r.model==='minicpm'?'disabled in this run':'not exposed'):r.thinking_tokens.toLocaleString()+' tokens')+'; generated tokens: '+r.generated_tokens.toLocaleString()+'; first answer text: '+(r.first_answer_seconds===null?'unavailable':r.first_answer_seconds.toFixed(2)+' s')+'.'));
   if(r.native_text_end_marker_applied)card.append(make('p','MiniCPM text ends at the first TTS end marker, following its official text extractor; original generation costs are retained.'));if(r.source_review){if(r.automatic_score&&r.score&&r.automatic_score.supported_correct!==r.score.supported_correct)card.append(make('p','Original automatic label: '+(r.automatic_score.supported_correct?'fully supported':'not fully supported')+'; corrected by source review.'));card.append(make('p','Source review: '+r.source_review.reason));}host.append(card);});
  $('case-status').textContent=rows.length+' saved answers shown.';
 }
 $('case-load').addEventListener('click',async()=>{const b=$('case-load');b.disabled=true;try{if(!data){const values=await Promise.all(['full-expansion-answers.json','full-cases.json'].map(async name=>{const r=await fetch('../research/note-functions/'+name+'?v=DATA_VERSION');if(!r.ok)throw new Error('HTTP '+r.status);return r.json();}));data=values[0];cases=values[1].questions;}render();}catch(error){$('case-status').textContent='Could not load answers: '+error.message;}finally{b.disabled=false;}});
 ['case-question','case-model','case-seed','case-voice'].forEach(id=>$(id).addEventListener('change',render));
 const params=new URLSearchParams(location.search);
 [['question','case-question'],['model','case-model']].forEach(([key,id])=>{if(params.has(key)&&Array.from($(id).options).some(o=>o.value===params.get(key)))$(id).value=params.get(key);});
 if(params.has('question'))$('case-load').click();
 function reveal(){const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(!target)return;for(let p=target;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;requestAnimationFrame(()=>{const nav=document.querySelector('.site-nav');window.scrollTo({top:scrollY+target.getBoundingClientRect().top-(nav?nav.getBoundingClientRect().bottom:0)-16,behavior:'instant'});});}
 addEventListener('hashchange',reveal);addEventListener('load',reveal);
})();
'''

def main():
 d=read('full-expansion.json');stats=read('full-statistics.json');cases=read('full-cases.json')['questions'];progress=read('progress.json')
 body='<header class="hero"><p class="small">S2 experiments · '+e(d['updated'][:10])+'</p><h1>Answer quality and thinking cost</h1></header><section id="findings"><h2>Main findings</h2><ul>'
 for x in progress['brief']:body+='<li>'+e(x['text'])+' '+link(x['url'],'Details')+'</li>'
 body+='</ul></section><nav class="page-menu" aria-label="On this page">'+''.join(link('#'+key,label)for key,label in [('full-set','Results'),('cost','Thinking and cost'),('examples','Browse answers'),('methods','Methods'),('evaluation','Scoring'),('review','Score review'),('appendix','Earlier studies'),('next','Next steps')])+'</nav>'
 body+='<section id="full-set"><span id="results"></span><h2>1. Results on 105 questions</h2><p>The same 105 questions from 26 meetings are evaluated in every condition. Text Thinking uses two seeds; each other model uses one. '+f"{d['outputs']:,}/{d['planned_outputs']:,} planned answers are saved."+' Counts include empty final outputs; these remain evaluation cases. '+e(progress['completion_note'])+'</p><p><strong>Accuracy status:</strong> '+e(d['scoring'])+'</p>'
 empty_by_model={model:sum(r['empty_answers']for r in d['summary']if r['model']==model)for model in MODELS}
 body+='<p>Empty final answers: '+e('; '.join(MODELS[model]+': '+str(count)for model,count in empty_by_model.items()))+'. These answers are scored incorrect, and their generated tokens remain in the cost totals.</p>'
 for branch,idx,title in [('text',1,'Text S2'),('audio',2,'Audio S2')]:
  rows=[]
  for r in d['summary']:
   if r['branch']!=branch:continue
   m=r['metrics'];timing='Batched; excluded'if r['model']=='instruct'else number(m['first_answer_seconds']['mean'],2)if r['complete']else'Pending'
   if r['complete']and r['model']!='instruct'and m['first_answer_seconds']['count']<r['outputs']:timing+=' ('+str(m['first_answer_seconds']['count'])+' timed)'
   rows.append([MODELS[r['model']],NAMES[r['condition']],IDENTITY[r['identity']],str(r['outputs'])+'/'+str(r['planned']),score(r),str(r['source_reviewed_matches'])+'/'+str(r['outputs']),number(m['thinking_tokens']['mean'])if r['model']in ['thinking','qwen-thinking']and r['complete']else'Disabled'if r['model']=='minicpm'else'Not exposed'if r['model']=='instruct'else'Pending',timing])
  body+=table(idx,title+'; fully supported counts use scored outputs, with missing judgments stated explicitly. Reviewed or empty counts source-checked responses and empty-answer failures; thinking tokens and seconds are means.',['Model','Condition','Speaker input','Saved / planned','Fully supported','Reviewed or empty','Thinking tokens','First text (s)'],rows)
 if all(g['complete']for g in d['groups']):
  help_url='?'+urlencode(dict(question='scale:IB4003-S075-Q3',model='qwen-thinking'))+'#examples'
  harm_url='?'+urlencode(dict(question='pilot:P-EN-timeline',model='qwen-thinking'))+'#examples'
  body+='<p>Saved notes can recover a missed fact and can also introduce a wrong interpretation. For example, Qwen audio changes an office headcount from 18 to the correct 15 with notes ('+link(help_url,'compare the headcount answers')+'), while its notes conditions incorrectly treat a copied timeline as referring only to a prototype outline ('+link(harm_url,'compare the timeline answers')+'). These cases illustrate why accuracy and request-time work are assessed together.</p>'
 body+='<p><a href="../research/note-functions/full-expansion.json">Coverage and scores (JSON)</a> · <a href="../research/note-functions/full-statistics.json">Paired statistics and costs (JSON)</a> · <a href="../research/note-functions/full-expansion-answers.json">Native answers and score status (JSON)</a></p></section>'
 body+='<section id="cost"><h2>2. Request-time thinking and complete cost</h2><p>Request-time thinking tokens are generated after the participant asks the question. Earlier note generation is amortized thinking and is counted separately. Native reasoning-token counts are reported for Qwen Thinking and Qwen Omni. MiniCPM thinking mode is disabled in these runs; Instruct has no separate thinking channel. Figure 1 includes all earlier note work once per meeting and speaker condition, including unused updates and rejected operations. Figure 2 tests paired changes relative to reactive answering. First-text timing includes incorrect outputs; accuracy is reported alongside it.</p>'
 for idx,name,caption in [(1,'full-generated-cost','Generated tokens for 105 requests at seed 23, with request-time generation shown separately from the complete cost. The horizontal scales differ between panels. The complete cost adds all earlier note generation; input processing, audio encoding and scoring are separate costs.'),(2,'full-paired-work','Mean paired changes from reactive answering; negative values mean less request-time work. Intervals are 95% confidence intervals from resampling meetings. Text retains both seeds. Each point states its valid-pair count; missing first-text times remain reported in the data. Empty or capped outputs remain in token costs.')]:
  if d.get('figures',{}).get(name):body+='<figure id="fig-'+name+'"><div class="plot"><img src="'+asset(name+'.svg')+'" alt="'+e(caption)+'"></div><figcaption><strong>Figure '+str(idx)+'.</strong> '+e(caption)+' '+link(asset(name+'.pdf'),'PDF')+'</figcaption></figure>'
 if all(g['complete']for g in d['groups']):
  history=next(r for r in stats['comparisons']if r['model']=='thinking'and r['condition']=='quotes_history')
  thinking=history['metrics']['thinking_tokens'];both=history['quality_and_work']['both_supported']
  body+='<p>For text Thinking, quotes plus earlier evidence reduce mean request-time thinking by '+number(-thinking['mean_change'])+' tokens, while the median paired change is '+number(thinking['median_change'],1)+' more tokens. The uncertainty interval includes zero. Among the '+str(both['pairs'])+' pairs whose two answers both receive fully supported labels, mean thinking instead increases by '+number(both['metrics']['thinking_tokens']['mean_change'])+' tokens. The lower overall mean therefore does not describe a typical reduction across questions.</p>'
  audio=[r for r in stats['comparisons']if r['model']=='qwen-thinking']
  body+='<p>For Qwen audio, function notes increase first-text time by '+', and by '.join(number(r['metrics']['first_answer_seconds']['mean_change'],2)+' seconds '+('with labelled voice examples'if r['identity']=='labelled_voices'else'with audio alone')for r in audio)+'. Both time intervals lie above zero, and this slower onset also occurs in pairs whose two answers are fully supported. The accuracy changes run in opposite directions across the two speaker conditions; both accuracy intervals include zero.</p>'
  mini=next(r for r in stats['comparisons']if r['model']=='minicpm'and r['identity']=='audio_only')
  body+='<details><summary>MiniCPM onset timing</summary><p>With audio alone, MiniCPM first text starts '+number(-mini['metrics']['first_answer_seconds']['mean_change'],2)+' seconds earlier on average across '+str(mini['metrics']['first_answer_seconds']['pairs'])+' matched timing pairs, while the median change is nearly zero. Fully supported labels change from 42 to 41 of 105. Its thinking mode is disabled, so this is an onset measurement alongside answer quality.</p></details>'
 rows=[]
 for r in stats['comparisons']:
  accuracy=r['accuracy'];change=(f"{100*accuracy['mean_change']:+.1f} [{100*accuracy['meeting_95_percent_interval'][0]:+.1f}, {100*accuracy['meeting_95_percent_interval'][1]:+.1f}]"if accuracy.get('meeting_95_percent_interval')is not None else'Pending')
  rows.append([MODELS[r['model']],NAMES[r['condition']],IDENTITY[r['identity']],change,interval(r['metrics']['thinking_tokens']),interval(r['metrics']['first_answer_seconds'],2)if'first_answer_seconds'in r['metrics']else'Batched; excluded'])
 body+='<details><summary>Exact paired changes and generated-token totals</summary>'+table(3,'Mean change [95% interval] relative to reactive answering; pp means percentage points, and accuracy retains the stated score-review status.',['Model','Condition','Speaker input','Accuracy change (pp)','Thinking-token change','First-text change (s)'],rows)
 rows=[[MODELS[r['model']],NAMES[r['condition']],IDENTITY[r['identity']],number(r['request_input_tokens']),number(r['earlier_input_tokens']),number(r['request_generated_tokens']),number(r['earlier_generated_tokens']),number(r['combined_generated_tokens'])]for r in stats['total_generated_cost']if r['complete']]
 body+=table(4,'Input and generated tokens for one seed-23 set of 105 questions; writer work is counted once per hypothetical condition. Native token counts are compared within each model.',['Model','Condition','Speaker input','Request input','Earlier input','Request generation','Earlier generation','Combined generation'],rows)+'</details></section>'
 body+='<section id="examples"><h2>3. Browse actual answers</h2><p>Choose a question and model to compare its exact final answers, reference facts, transcript evidence and score review. Native reasoning text is excluded.</p><div class="case-controls"><label>Question<select id="case-question">'+''.join('<option value="'+e(q['id'],quote=True)+'">'+e(q['meeting']+' · '+q['question'])+'</option>'for q in cases)+'</select></label><label>Model<select id="case-model">'+''.join('<option value="'+m+'"'+(' selected'if m=='thinking'else'')+'>'+name+'</option>'for m,name in MODELS.items())+'</select></label><label>Seed<select id="case-seed"><option value="all">All saved seeds</option><option>23</option><option>47</option></select></label><label>Speaker input<select id="case-voice"><option value="all">All available</option>'+''.join('<option value="'+key+'">'+label+'</option>'for key,label in IDENTITY.items())+'</select></label></div><button id="case-load" type="button">Load answers</button><p id="case-status" role="status">Answers load when requested.</p><div id="case-list"></div></section>'
 writer_quality=''
 for model in ['minicpm','qwen-thinking']:
  rows=[r for key,r in stats['writer_cost'].items()if key.startswith(model+'|')]
  if rows:writer_quality+='<p>'+e(MODELS[model])+': '+str(sum(r['updates']for r in rows))+' note updates; '+str(sum(r['length_stops']for r in rows))+' reached the output-token limit; '+str(sum(r['parse_errors']for r in rows))+' produced no usable operation; '+str(sum(r['rejected_operations']for r in rows))+' operations were rejected by the program. These mechanical counts do not establish whether the saved facts are correct.</p>'
 body+='<section id="methods"><span id="design"></span><span id="audio-s2"></span><h2>4. Inputs and saved notes</h2><ul><li>Reactive text S2 receives the complete available speaker-attributed reference transcript and the participant’s question.</li><li>The text conditions add current generated facts, original transcript passages supporting those facts, or those passages plus earlier saved evidence, respectively.</li><li>The text writer receives each new 25–40 second transcript segment, ten seconds of recent context and one current note state.</li><li>Audio S2 receives the past recording and spoken question, either alone or with labelled voice examples drawn only from earlier speech.</li><li>The audio writer receives the new audio segment, recent audio and one current note state; it does not receive the future question or a reference transcript.</li><li>All note updates use the same functions and preserve changes to earlier commitments and decisions.</li></ul><p>The fixed schedule groups meaningful speech into segments; silence and a very short final remainder need not cause a note update. Audio encoders can divide these segments into smaller windows without changing their content or thinking boundaries. The answerer receives one current note state. This is offline causal replay: the writer never sees the future question, and the final call selects only notes from before the question’s insertion time. Real-time availability of unfinished notes remains a separate test.</p><details id="functions"><summary>Memory functions and event changes</summary><p><code>add_note</code> records a distinct fact; <code>update_note</code> changes the same task; <code>delete_note</code> removes a duplicate or error; <code>link_notes</code> relates events; <code>no_change</code> skips unchanged material. The program validates arguments and available source IDs before applying edits. For example, a proposed Friday deadline can change to an agreed Monday deadline while retaining both source passages and the earlier version. Current notes are limited to 4,096 tokens, with eight recent changes.</p><p>'+link('../research/note-functions/functions.json','Text function definitions and instructions')+'</p>'+writer_quality+'</details><details><summary>Model context and timing</summary><p>Qwen3-30B-A3B Instruct and Thinking use reference transcripts. Audio models are MiniCPM-o 4.5 and Qwen3-Omni-30B-A3B Thinking. Qwen audio retains all history for every question. MiniCPM retains all history for 103/105 questions; its two longest inputs remove the oldest 303 or 219 seconds. Each model uses the same selected raw history across all its answer conditions.</p><p>Full-set jobs use one A100 SXM4 80 GB each, with model weights, the audio encoder when needed, and an 8 GiB KV cache on GPU 0. At most two independent jobs are active; the remaining Qwen questions are partitioned between jobs without changing per-answer settings. Model services are job-private and TTS is disabled. vLLM uses CUDA graphs and four concurrent note requests; controlled request-time answers are serial with cold prefix and audio caches. Instruct answers were batched, so their times are excluded from the latency comparison. Audio timing includes waveform loading and preprocessing.</p></details></section>'
 body+='<section id="evaluation"><h2>5. Scoring</h2><p><strong>Required-fact correctness</strong> checks whether the answer supplies every fact requested by the question. <strong>Fully supported correctness</strong> also rejects material extra claims that the available transcript does not support. The evaluator receives the question, candidate answer, reference fact checklist and past transcript; it must quote the candidate’s words and cite supporting transcript IDs. Missing facts cannot be filled from the reference. Speaker identity can be expressed by a name, a speaker label or an unambiguous reference to an earlier utterance or audio segment.</p><p>Mechanical checks reject malformed judgments, unavailable transcript IDs and quotations absent from the candidate. Such cases await review rather than becoming wrong model answers. Empty final answers are scored wrong and retained. Native output tokens, thinking tokens and latency are collected independently of semantic scoring. MiniCPM final text ends at the first TTS end marker, following its official chat extractor; later control fragments are excluded from answer scoring while their generated-token costs remain counted.</p><p>The automatic scorer matched '+str(d['qualification'].get('supported_correct_agreements',0))+'/'+str(d['qualification'].get('cases',315))+' fully supported labels in the source-reviewed control set. Its remaining labels are provisional. Codex source review corrects individual responses and is recorded with transcript IDs and reasons; the answer browser shows that status. '+str(d['source_reviewed_matches'])+' saved outputs currently match source-reviewed responses.</p></section>'
 audit=d.get('blind_review_summary',{});body+='<p>In an additional check, Codex reviewed '+str(audit.get('cases',0))+' responses without seeing their automatic labels; '+str(audit.get('supported_agreements',0))+' fully supported labels agreed, and the disagreements were corrected.</p>'
 body+='<section id="review"><span id="scorer-review"></span><h3>Score review examples</h3>'
 for x in d.get('review_examples',[]):
  body+='<details><summary>'+e(x['question'])+'</summary><p><strong>Actual answer:</strong> '+e(x['answer'])+'</p><p><strong>Source review:</strong> '+e(x['reason'])+'</p><ul>'+''.join('<li>'+e(s['id']+' · '+s['speaker']+': '+s['text'])+'</li>'for s in x['source_evidence'])+'</ul></details>'
 body+='</section><details id="appendix"><summary>Earlier completed studies and implementation history</summary><p>The current full-set tables replace interim progress tables and small-pilot comparisons. Earlier completed studies remain available for reference:</p><ul><li>'+link('full-answering-results.html','Earlier full S1 and S2 evaluation')+'</li><li>'+link('../research/note-functions/analysis.json','Earlier JSON versus native-call results and answers')+'</li><li>'+link('../research/note-functions/diagnostic.json','Completed 12-question text pilot')+'</li><li>'+link('../research/note-functions/audio-pilot.json','Completed two-question audio pilot')+'</li></ul>'
 for key in ['progress','update-feedback','initial-pilot','followup','audio-pilot-results','diagnostic-results','fig-answer-accuracy','fig-paired-request-work','fig-total-generated-cost','fig-diagnostic-paired','fig-diagnostic-cost']+['review-case-'+str(i)for i in range(1,13)]+['diagnostic-case-'+str(i)for i in range(1,13)]:body+='<span id="'+key+'"></span>'
 body+='<p>These earlier section links now point to this archive index. Full-set outputs and their source reviews appear in the answer browser above. A cluster node failure interrupted Qwen note generation; checkpoint recovery preserves completed updates and generates only the missing portion. Runtime completion is recorded separately from answer accuracy.</p></details><section id="next"><h2>Next steps and goals</h2><ul>'+''.join('<li>'+e(x)+'</li>'for x in d['next_steps'])+'</ul><p>'+link('../todo.html','Project checklist')+' · '+link('../daily-log.html','Daily log')+'</p></section>'
 js=JS.replace('MODEL_NAMES',json.dumps(MODELS)).replace('CONDITION_NAMES',json.dumps(NAMES)).replace('DATA_VERSION',d['updated'])
 extra='.page-menu{display:flex;flex-wrap:wrap;gap:.5rem 1rem;padding:.8rem 0;border-block:1px solid var(--border)}.case-controls{display:grid;gap:.8rem;grid-template-columns:1fr}.case-controls label{display:block}.case-controls select{width:100%;min-width:0}.case-card{border-top:1px solid var(--border);padding:.6rem 0}.plot{overflow-x:auto;background:white}.plot img{width:100%;min-width:760px;height:auto}pre.native{white-space:pre-wrap;overflow-wrap:anywhere;max-height:24rem;overflow:auto}details{margin:1rem 0}summary{cursor:pointer}button{margin-top:.8rem;padding:.5rem 1rem}@media(min-width:900px){.case-controls{grid-template-columns:3fr 2fr 1fr 2fr}}'
 page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="Full-set S2 results: answer quality, request-time thinking, latency and complete note-generation cost."><title>Latest S2 results · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><style>'+CSS+extra+'</style></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><div class="container collection-nav">'+experiment_subtabs('note-functions')+'</div><main id="main" class="container results">'+body+'</main><script>'+js+'</script></body></html>\n'
 (ROOT/'experiments/note-functions.html').write_text(page)
if __name__=='__main__':main()
